function largestSliceSwing(nums: number[]): number {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    let s = 0;
    for (let j = i; j < nums.length; j++) {
      s += nums[j];
      best = Math.max(best, Math.abs(s));
    }
  }
  return best;
}

