function largestSliceSwing(nums: number[]): number {
  let curMax = 0, curMin = 0, best = 0;
  for (const x of nums) {
    curMax = Math.max(0, curMax + x); // empty slice is allowed
    curMin = Math.min(0, curMin + x);
    best = Math.max(best, curMax, -curMin);
  }
  return best;
}

